import stylesText from './food-log.css?inline';
import bindingStylesText from '../barcode-binding.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';

const styles = cssStyleSheet(stylesText);
const bindingStyles = cssStyleSheet(bindingStylesText);
import { LABEL_READ_FIELDS, MEAL_TYPES, inStoreItemCode } from '@motivation/shared';
import type { LabelReadResult, MealType, FoodItemBarcodeMatch, MealWithIngredients } from '@motivation/shared';
export type { FoodLogEntry } from './food-log-detail.component.js';
import { HealthService, LabelReadError } from '../../../services/health.service.js';
import { FilesService } from '../../../services/files.service.js';
import type { OFFProduct, OffLookupOutcome } from '../../../services/openfoodfacts.service.js';
import {
    HEALTH_EVENTS,
    createScanBarcodeEvent,
    createAiEstimateEvent,
    type BindConsentChangeEvent,
} from '../health-events.js';
import { showBindingBound, showBindingOffer } from '../barcode-binding-banner.component.js';
import { FoodSearchPipeline, resolveScannedBarcode } from './food-search-pipeline.js';
import { getDefaultMealType } from '../health-utils.js';
import './food-search-results.component.js';
import './food-log-detail.component.js';
import './frequent-grid/frequent-grid.component.js';
import '../meal-log-detail/meal-log-detail.component.js';
import type { FoodSearchResults } from './food-search-results.component.js';
import type { FrequentGrid } from './frequent-grid/frequent-grid.component.js';
import type { FoodLogDetail, FoodLogDetailMode, LabelDraftTarget } from './food-log-detail.component.js';
import type { MealLogDetail } from '../meal-log-detail/meal-log-detail.component.js';

export type FoodLogMode = FoodLogDetailMode;
import { createComponentLogger } from '../../../utils/component-logger.js';

const DEFAULT_SEARCH_PLACEHOLDER = 'Search for food… (Enter to search online)';

/**
 * Story 338 — what an unreadable photo leaves behind: the same review surface,
 * every field blank and editable, nothing claimed. `per_100g` / 100 g is not an
 * assertion about the label (nothing was read off it) but the shape a hand-typed
 * row takes, and it is the one base that cannot be wrong for a density the user
 * is about to type themselves.
 */
const EMPTY_LABEL_DRAFT: LabelReadResult = {
    draft: {
        canonical_name: '',
        display_name: '',
        source: 'label_photo',
        base_amount: 100,
        base_unit: 'g',
    },
    basis: 'per_100g',
    unread: [...LABEL_READ_FIELDS],
    confidence_score: 0,
    notes: '',
};

const template = document.createElement('template');
template.innerHTML = `
    <div class="food-log-container">
        <div id="search-view">
            <barcode-binding-banner id="map-barcode-banner" class="map-banner" kind="offer" hidden></barcode-binding-banner>
            <div class="search-bar">
                <input type="text" id="search-input" placeholder="Search for food… (Enter to search online)">
            </div>
            <div class="alt-log-actions" id="alt-log-actions" hidden>
                <button class="alt-log-btn" id="scan-btn">Scan Barcode</button>
                <button class="alt-log-btn" id="label-btn">Photograph Label</button>
                <button class="alt-log-btn" id="ai-btn">AI Estimate</button>
            </div>
            <!-- Story 338: no capture= attribute on purpose — with it, a phone
                 goes straight to the camera and the gallery is unreachable, and
                 the AC is "captures OR uploads". -->
            <input type="file" id="label-input" accept="image/jpeg,image/png,image/webp" hidden>
            <p class="pick-hint" id="pick-hint" hidden>Tap the food this barcode means</p>
            <frequent-grid id="frequent-grid"></frequent-grid>
            <div id="search-loading" class="loading-text" hidden>Searching…</div>
            <div id="search-error" class="error-text" hidden></div>
            <food-search-results id="search-results-component"></food-search-results>
        </div>

        <div id="detail-view" hidden>
            <barcode-binding-banner id="map-barcode-bound" class="map-bound" kind="bound" hidden></barcode-binding-banner>
            <!-- Story 353: a match with no nutrition gets 338's label read here,
                 because a scan that resolved never shows the search view's button. -->
            <div id="label-offer" class="label-offer" hidden>
                <p class="label-offer-text">No nutrition for this one — photograph the label to fill it in.</p>
                <button class="alt-log-btn" id="label-offer-btn" type="button">Photograph Label</button>
                <p class="error-text" id="label-offer-error" hidden></p>
            </div>
            <input type="file" id="label-offer-input" accept="image/jpeg,image/png,image/webp" hidden>
            <food-log-detail id="detail-component"></food-log-detail>
        </div>

        <div id="meal-detail-view" hidden>
            <meal-log-detail id="meal-detail-component"></meal-log-detail>
        </div>

        <div id="lookup-loading" class="loading-text" hidden>Looking up product…</div>
        <div id="label-loading" class="loading-text" hidden>Reading the label…</div>
    </div>
`;

export class FoodLog extends HTMLElement {
    private searchTimeout: ReturnType<typeof setTimeout> | null = null;
    private showScanBarcodeActionValue = false;
    private showAiEstimateActionValue = false;
    /** Story 338 — off by default, so the meal/ingredient surfaces are untouched. */
    private showLabelReadActionValue = false;
    /** Story 353 — the match on the detail view, when it came with no nutrition. */
    private emptyMatch: LabelDraftTarget | null = null;
    private defaultMealTypeValue: MealType | null = null;
    private modeValue: FoodLogMode = 'log';
    private readonly log = createComponentLogger('food-log');
    /** Story 373: the same search the meal picker runs, with saved meals among the results. */
    private readonly foodSearch = new FoodSearchPipeline({
        results: () => this.shadowRoot!.getElementById('search-results-component') as FoodSearchResults,
        loading: () => this.shadowRoot!.getElementById('search-loading')!,
        error: () => this.shadowRoot!.getElementById('search-error')!,
    }, this.log, { meals: true });

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles, bindingStyles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    connectedCallback(): void {
        const shadow = this.shadowRoot!;
        const searchInput = shadow.getElementById('search-input') as HTMLInputElement;

        searchInput.addEventListener('input', () => {
            if (this.searchTimeout) clearTimeout(this.searchTimeout);
            // Story 276: an emptied box is not a search — drop the stale results
            // and hand the space back to the frequent-items grid immediately,
            // without waiting out the debounce.
            if (searchInput.value.trim() === '') {
                this.foodSearch.reset();
                this.showFrequentGrid();
                return;
            }
            this.searchTimeout = setTimeout(() => void this.performLocalSearch(searchInput.value.trim()), 300);
        });

        searchInput.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter') {
                if (this.searchTimeout) clearTimeout(this.searchTimeout);
                void this.performSearch(searchInput.value.trim());
            }
        });

        shadow.getElementById('scan-btn')!.addEventListener('click', () => this.dispatchEvent(createScanBarcodeEvent()));
        shadow.getElementById('ai-btn')!.addEventListener('click', () => this.dispatchEvent(createAiEstimateEvent()));

        // Story 338 — photograph the label. Stays inside this component rather
        // than bubbling to the screen: the draft's destination is the detail
        // view this component already owns, so a round trip through the screen
        // would only move the same call one level up.
        const readPickedLabel = (event: Event, target: LabelDraftTarget | null) => {
            const input = event.target as HTMLInputElement;
            const file = input.files?.[0];
            // Cleared before the await: picking the same file twice in a row
            // fires no `change` otherwise, which reads as a dead button after a
            // failed read — the exact moment you want to retry.
            input.value = '';
            if (file) void this.readLabelFromPhoto(file, target);
        };
        shadow.getElementById('label-btn')!.addEventListener('click', () => {
            shadow.getElementById('label-input')!.click();
        });
        shadow.getElementById('label-input')!.addEventListener('change', (event) => readPickedLabel(event, null));
        // Story 353: its own input, so which match a photo is for is decided by
        // where it was picked, not by a field a cancelled picker could leave stale.
        shadow.getElementById('label-offer-btn')!.addEventListener('click', () => {
            shadow.getElementById('label-offer-input')!.click();
        });
        shadow.getElementById('label-offer-input')!.addEventListener('change', (event) => readPickedLabel(event, this.emptyMatch));

        // Story 344: ticking the box is the whole act of consent. It also turns on the
        // pick hint and the search placeholder, so the screen only claims to be asking
        // "which food is this?" once that is actually what the next tap will mean.
        shadow.getElementById('map-barcode-banner')!.addEventListener(HEALTH_EVENTS.BIND_CONSENT_CHANGE, (event: BindConsentChangeEvent) => {
            this.bindConsentValue = event.detail.consent;
            if (this.pendingBarcodeValue) this.setPendingBarcode(this.pendingBarcodeValue, this.bindConsentValue);
        });

        // Story 344: the detail view carries the same opt-in for the item-code case,
        // where there is no pick and so no banner. One consent flag either way.
        shadow.getElementById('detail-component')!.addEventListener(HEALTH_EVENTS.BIND_CONSENT_CHANGE, (event: BindConsentChangeEvent) => {
            this.bindConsentValue = event.detail.consent;
        });

        // Story 342: re-arm the question on the code that was just bound. Re-binding
        // replaces (340's newest-intent-wins), so this corrects a wrong pick without
        // needing an unbind. The banner's MAP_BARCODE_CHANGE carries on to the screen,
        // which puts the code back in the URL.
        shadow.getElementById('map-barcode-bound')!.addEventListener(HEALTH_EVENTS.MAP_BARCODE_CHANGE, () => {
            this.setBoundBarcode(null);
        });

        // Story 373: Load More pages this component's own search, as in the meal picker.
        this.addEventListener(HEALTH_EVENTS.LOAD_MORE_OFF, (event: Event) => {
            event.stopPropagation();
            void this.foodSearch.loadMore();
        });

        // Note: SELECT_LIBRARY_ITEM, SELECT_OFF_ITEM and FOOD_LOG_BACK bubble past this
        // component to the screen. The screen drives view state via
        // lookupBarcode/lookupLibraryItem/showSearchView/showProduct/showLibraryItem.

        this.applyMealTypeSelection();
        this.updateAltLogActionsVisibility();

        // Propagate the current mode to the freshly-mounted child detail.
        const detail = shadow.getElementById('detail-component') as FoodLogDetail | null;
        if (detail) detail.mode = this.modeValue;
    }

    set showScanBarcodeAction(show: boolean) {
        this.showScanBarcodeActionValue = show;
        this.updateAltLogActionsVisibility();
    }

    set showAiEstimateAction(show: boolean) {
        this.showAiEstimateActionValue = show;
        this.updateAltLogActionsVisibility();
    }

    set showLabelReadAction(show: boolean) {
        this.showLabelReadActionValue = show;
        this.updateAltLogActionsVisibility();
        this.setEmptyMatch(this.emptyMatch);
    }

    set defaultMealType(mealType: string | null) {
        if (!mealType || !MEAL_TYPES.includes(mealType as MealType)) {
            this.defaultMealTypeValue = null;
        } else {
            this.defaultMealTypeValue = mealType as MealType;
        }
        this.applyMealTypeSelection();
    }

    async lookupBarcode(barcode: string): Promise<void> {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = false;

        const scan = await resolveScannedBarcode(barcode, this.log);
        shadow.getElementById('lookup-loading')!.hidden = true;
        // A code the library does not know yet stays pending, so saving can bind it; a plain
        // exact hit clears it, and the screen re-arms from the URL when a pick carries one.
        this.setPendingBarcode(scan.pending);
        if (scan.kind === 'library') {
            this.showLibraryItem(scan.item);
            return;
        }
        if (scan.kind === 'product') {
            this.showProduct(scan.product);
            return;
        }

        this.logUnresolvedScan(barcode, scan.library, scan.off, scan.status);

        // Story 340 — nothing could answer this code, so the user's next pick becomes
        // the answer. It is re-scanned for days (13 times across 5.2 days, in the logs
        // that motivated this).
        shadow.getElementById('search-view')!.hidden = false;
        const errorEl = shadow.getElementById('search-error')!;
        errorEl.textContent = `Product not found for barcode ${barcode}.`;
        errorEl.hidden = false;
    }

    /**
     * Story 339 — scans of each barcode within this visit. A dead-end code is re-tried
     * for days (13 times across 5.2 days in the logs that prompted this), and eleven
     * identical `warn` lines is the noise story 332 is about. So: one line when it first
     * fails, one more when the repetition itself becomes the finding, `debug` for the
     * rest — the count rides along either way.
     */
    private readonly scanAttempts = new Map<string, number>();
    private readonly repeatWarned = new Set<string>();
    private static readonly REPEAT_WARN_AT = 3;

    private logUnresolvedScan(
        barcode: string,
        library: 'miss' | 'failed',
        off: OffLookupOutcome,
        status: number | undefined,
    ): void {
        const attempts = (this.scanAttempts.get(barcode) ?? 0) + 1;
        this.scanAttempts.set(barcode, attempts);
        const context = {
            barcode,
            // Classification only — spike 336 found OFF answers 20 of 28 prefix-2 codes,
            // so this must never become a reason to skip the lookup.
            barcodeClass: inStoreItemCode(barcode) ? 'in_store' : 'gs1',
            itemCode: inStoreItemCode(barcode) ?? undefined,
            library,
            off,
            status,
            attempts,
        };

        if (attempts === 1) {
            this.log.warn('barcode scan unresolved', context);
        } else if (attempts >= FoodLog.REPEAT_WARN_AT && !this.repeatWarned.has(barcode)) {
            this.repeatWarned.add(barcode);
            this.log.warn('barcode scan repeatedly unresolved', context);
        } else {
            this.log.debug('barcode scan unresolved (repeat)', context);
        }
    }

    /**
     * Story 340 — the code awaiting a food to be mapped onto. Set when a scan dead-ends;
     * cleared once a pick has been mapped, or when the user abandons the search.
     */
    private pendingBarcodeValue: string | null = null;
    /** Story 342 — the code just bound, so the detail view can confirm what happened. */
    private boundBarcodeValue: string | null = null;
    /** Story 344 — the opt-in. Nothing is bound unless the user ticked the box. */
    private bindConsentValue = false;

    get pendingBarcode(): string | null {
        return this.pendingBarcodeValue;
    }

    /**
     * Story 342 — the pending question is a MODE, not a line of text.
     *
     * It was a 0.85rem box below the frequent grid, and "pick one below" pointed at an
     * empty results list while the pickable things sat above it. Nothing else on screen
     * changed, and the code itself was small enough that binding the wrong one read as
     * success (2026-09-14: a 12-digit misread bound instead of the 13-digit sticker).
     * So: a banner at the TOP, the code at a size you can check against the label, the
     * scope spelled out, the grid relabelled as the picker it already is, and a way out.
     */
    setPendingBarcode(barcode: string | null, consent = false): void {
        this.pendingBarcodeValue = barcode;
        this.bindConsentValue = Boolean(barcode) && consent;
        // Story 344: the hint belongs to the offer, not to the screen. Un-ticked, the pick is
        // just a pick — "tap the food this barcode means" would describe something the app
        // is not going to do. Story 373: shared with the meal picker.
        if (this.shadowRoot) showBindingOffer(this.shadowRoot, barcode, this.bindConsentValue, DEFAULT_SEARCH_PLACEHOLDER);
    }

    /**
     * Story 344 — a mapping is only ever written when this is true.
     *
     * 342 bound on the pick and announced it either side; the owner still bound a code
     * without realising, because picking a food is what you do when a scan fails and the
     * binding rode along with it (2026-09-14 18:21, `956057011523` → Chili Powder). The
     * pick is no longer consent. This is.
     */
    get bindConsent(): boolean {
        return this.bindConsentValue;
    }

    /**
     * Story 342 — what the binding actually did, shown on the detail view the pick lands
     * on. Previously the only trace of a successful map was a `debug` log line, so a
     * degraded binding (a code with no item code, which answers one sticker and nothing
     * else) was indistinguishable from the one the user wanted.
     *
     * "Change" re-arms the question rather than deleting the mapping: `mapBarcode`'s
     * newest-intent-wins rule (story 340) means re-binding replaces, so a correction
     * needs no unbind endpoint.
     */
    setBoundBarcode(barcode: string | null, foodName?: string): void {
        this.boundBarcodeValue = barcode;
        if (this.shadowRoot) showBindingBound(this.shadowRoot, barcode, foodName);
    }

    get boundBarcode(): string | null {
        return this.boundBarcodeValue;
    }

    /**
     * Story 338 — photograph a nutrition table, get a draft food item.
     *
     * Upload, read, review. The upload must actually land: the read happens on
     * the server against the stored bytes, so a queued (offline) upload has
     * nothing to read and is reported as such rather than left spinning — the
     * same call the AI estimate's synchronous path makes.
     *
     * The two failure paths are deliberately different, because the right next
     * action is different:
     *   - **unreadable** (422) — the model saw the photo and got nothing usable
     *     out of it. Another photo of the same crumpled label will not do
     *     better, so the draft surface opens anyway, empty and editable, with
     *     the raw reason on it. That is the AC's "leaves the manual form open
     *     with whatever fields it did get", and here it got none.
     *   - **anything else** — GPU busy, Ollama down, offline, timeout. The
     *     photo is fine and retrying is the fix, so this stays on the search
     *     view with the raw error and the button still there.
     *
     * Story 353: `target` is the empty match the read fills in. Both outcomes
     * carry it into the draft, and a retryable failure returns to that match —
     * with its own offer, not the search view's button — rather than to search.
     */
    async readLabelFromPhoto(file: File, target: LabelDraftTarget | null = null): Promise<void> {
        const shadow = this.shadowRoot!;
        this.abortOffSearch();
        const errorEl = target ? shadow.getElementById('label-offer-error')! : shadow.getElementById('search-error')!;
        errorEl.hidden = true;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('label-loading')!.hidden = false;

        try {
            const upload = await FilesService.uploadImageOrQueue('ai', file, file.name || 'label.jpg');
            if (upload.status !== 'uploaded') {
                throw new Error('Your photo is queued for upload (offline or server unreachable). Reading a label needs the server — try again once it has uploaded.');
            }
            const result = await HealthService.readNutritionLabel(upload.image_path);
            this.log.debug('label read produced a draft', {
                basis: result.basis,
                base_amount: result.draft.base_amount,
                base_unit: result.draft.base_unit,
                named: !!result.draft.display_name,
                unread: result.unread.length,
            });
            shadow.getElementById('label-loading')!.hidden = true;
            this.showLabelDraft(result, undefined, target);
        } catch (err) {
            shadow.getElementById('label-loading')!.hidden = true;
            const message = err instanceof Error ? err.message : String(err);
            if (err instanceof LabelReadError && err.reason === 'unreadable') {
                this.log.warn('label read produced nothing — opening an empty draft to fill in by hand', { error: message });
                this.showLabelDraft(EMPTY_LABEL_DRAFT, message, target);
                return;
            }
            this.log.warn(`label read failed; the ${target ? 'match' : 'search view'} stands`, { error: message });
            shadow.getElementById(target ? 'detail-view' : 'search-view')!.hidden = false;
            errorEl.textContent = message;
            errorEl.hidden = false;
        }
    }

    /** Story 338 — the read label, opened for review in the surface OFF products already use. */
    showLabelDraft(result: LabelReadResult, problem?: string, target: LabelDraftTarget | null = null): void {
        this.abortOffSearch();
        // The offer is answered: what is on screen now is the draft it produced.
        this.setEmptyMatch(null);
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = true;
        shadow.getElementById('label-loading')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = false;
        // A label read has no barcode of its own, so a pending scan is still
        // pending — the food this creates is exactly what that code should mean.
        this.setBoundBarcode(null);
        const detail = shadow.getElementById('detail-component') as FoodLogDetail;
        detail.showLabelDraft(result, problem, target);
        // Story 353: a library match saves as an update of a row that already owns
        // its code, and that save maps nothing — so it must not promise to.
        detail.setPendingBind(target?.kind === 'library' ? null : this.pendingBarcodeValue, this.bindConsentValue);
        this.applyMealTypeSelection();
    }

    /**
     * Story 353 — the match a label read can fill in, or null. "Empty" means no
     * energy value: OFF turns every missing nutriment into 0, and energy is what
     * this app counts — a match without it logs as 0 kcal whatever else it has.
     * A real 0 kcal product gets the offer too; it is an offer, not a redirect.
     */
    private setEmptyMatch(match: LabelDraftTarget | null): void {
        this.emptyMatch = match;
        const shadow = this.shadowRoot!;
        shadow.getElementById('label-offer')!.hidden = !(match && this.showLabelReadActionValue);
        const error = shadow.getElementById('label-offer-error')!;
        error.textContent = '';
        error.hidden = true;
    }

    showProduct(product: OFFProduct): void {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = false;
        this.setEmptyMatch((product.calories_per_100g ?? 0) > 0 ? null : { kind: 'product', product });
        const detail = shadow.getElementById('detail-component') as FoodLogDetail;
        detail.showProduct(product);
        // Story 342/344: offer the binding before the save — set after showProduct, which
        // owns the match note and would otherwise race it.
        detail.setPendingBind(this.pendingBarcodeValue, this.bindConsentValue);
        this.applyMealTypeSelection();
    }

    async showLibraryItem(item: FoodItemBarcodeMatch, initialAmount?: number): Promise<void> {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = false;
        this.setEmptyMatch((item.calories_per_base ?? 0) > 0 ? null : { kind: 'library', item });
        const detail = shadow.getElementById('detail-component') as FoodLogDetail;
        detail.showLibraryItem(item, initialAmount);
        // A library pick binds immediately, so the confirmation bar carries the news —
        // the "will be remembered" note would be stale here. The bar was armed from the
        // URL before the item loaded; now that it has, name the food in it. Story 369: an
        // item-code suggestion was not picked, so the binding is offered, as on an OFF match.
        detail.setPendingBind(item.matched_by === 'item_code' ? this.pendingBarcodeValue : null, this.bindConsentValue);
        if (this.boundBarcodeValue) this.setBoundBarcode(this.boundBarcodeValue, item.display_name);
        this.applyMealTypeSelection();
    }

    showMeal(meal: MealWithIngredients): void {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = false;
        const detail = shadow.getElementById('meal-detail-component') as MealLogDetail;
        if (this.defaultMealTypeValue) detail.defaultMealType = this.defaultMealTypeValue;
        detail.showMeal(meal);
    }

    async lookupLibraryItem(id: string): Promise<void> {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = false;

        try {
            const item = await HealthService.findFoodItem(id);
            shadow.getElementById('lookup-loading')!.hidden = true;
            if (item) {
                this.showLibraryItem(item);
            } else {
                this.showSearchView();
            }
        } catch {
            shadow.getElementById('lookup-loading')!.hidden = true;
            this.showSearchView();
        }
    }

    async lookupMeal(id: string): Promise<void> {
        this.abortOffSearch();
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = true;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = false;
        try {
            const meal = await HealthService.getMeal(id);
            shadow.getElementById('lookup-loading')!.hidden = true;
            this.showMeal(meal);
        } catch {
            shadow.getElementById('lookup-loading')!.hidden = true;
            this.showSearchView();
        }
    }

    showSearchView(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('search-view')!.hidden = false;
        shadow.getElementById('detail-view')!.hidden = true;
        shadow.getElementById('meal-detail-view')!.hidden = true;
        shadow.getElementById('lookup-loading')!.hidden = true;
        // The confirmation belongs to the detail view we are leaving.
        this.setBoundBarcode(null);

        // Back out of a detail view and the grid belongs on screen again —
        // unless a query is still in the box, in which case its results do.
        const searchInput = shadow.getElementById('search-input') as HTMLInputElement | null;
        if (searchInput?.value.trim()) {
            this.hideFrequentGrid();
        } else {
            this.showFrequentGrid();
        }
    }

    private get frequentGrid(): FrequentGrid | null {
        return this.shadowRoot?.getElementById('frequent-grid') as FrequentGrid | null;
    }

    private hideFrequentGrid(): void {
        const grid = this.frequentGrid;
        if (grid) grid.hidden = true;
    }

    /**
     * The grid re-queries on its way back in: an item logged during this visit
     * should be ranked as such when the user returns to the search view.
     */
    private showFrequentGrid(): void {
        const grid = this.frequentGrid;
        if (!grid) return;
        grid.hidden = false;
        void grid.refresh();
    }

    /** Typing: the library and meals, narrowing as you go (story 373: `FoodSearchPipeline`). */
    private performLocalSearch(query: string): void {
        if (query.length < 2) return;
        // Results are about to take over the space the grid occupies.
        this.hideFrequentGrid();
        void this.foodSearch.searchLocal(query);
    }

    /** Enter: the library, meals and Open Food Facts. */
    private performSearch(query: string): void {
        if (query.length < 2) return;
        this.hideFrequentGrid();
        this.foodSearch.search(query);
    }

    /** A pick or a lookup leaves the results to come back to; only the OFF leg stops. */
    private abortOffSearch(): void {
        this.foodSearch.stopOff();
    }

    private applyMealTypeSelection(): void {
        // Story 276: the grid ranks for the same slot the detail view will
        // preselect — including the time-of-day fallback when the flow was
        // entered without one in the URL.
        const mealType = this.defaultMealTypeValue ?? getDefaultMealType();
        this.frequentGrid?.setAttribute('meal-type', mealType);

        // The setter selects it; reaching into the detail's shadow root to do it again is gone (372).
        const detail = this.shadowRoot?.getElementById('detail-component') as FoodLogDetail | null;
        if (detail) detail.defaultMealType = mealType;
    }

    private updateAltLogActionsVisibility(): void {
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const actionsEl = shadow.getElementById('alt-log-actions');
        if (!actionsEl) return;
        const hasAltActions = this.showScanBarcodeActionValue || this.showAiEstimateActionValue || this.showLabelReadActionValue;
        actionsEl.hidden = !hasAltActions;

        const scanButton = shadow.getElementById('scan-btn') as HTMLButtonElement | null;
        if (scanButton) scanButton.hidden = !this.showScanBarcodeActionValue;

        const aiButton = shadow.getElementById('ai-btn') as HTMLButtonElement | null;
        if (aiButton) aiButton.hidden = !this.showAiEstimateActionValue;

        const labelButton = shadow.getElementById('label-btn') as HTMLButtonElement | null;
        if (labelButton) labelButton.hidden = !this.showLabelReadActionValue;
    }

    set mode(value: FoodLogMode) {
        this.modeValue = value;
        this.updateAltLogActionsVisibility();
        const detail = this.shadowRoot?.getElementById('detail-component') as FoodLogDetail | null;
        if (detail) detail.mode = value;
    }
}

if (!customElements.get('food-log')) {
    customElements.define('food-log', FoodLog);
}
