import './health-food-entry-screen.css';
import { HealthService } from '../../services/health.service.js';
import { navigate, goBack, exitFlow } from '../../router.js';
import type { NavigateOptions } from '../../router.js';
import { appTodayString, getAppTimeZone } from '../../services/app-timezone.service.js';
import { dateAndTimeToInstant } from '@motivation/shared';
import { buildSectionPage } from '../../utils/section-page.utils.js';
import './food-log/food-log.component.js';
import type { FoodLog, FoodLogEntry } from './food-log/food-log.component.js';
import type { FoodItem } from '@motivation/shared';
import type { OFFProduct } from '../../services/openfoodfacts.service.js';

import {
    HEALTH_EVENTS,
    type ScanBarcodeEvent,
    type AiEstimateEvent,
    type SelectLibraryItemEvent,
    type SelectOffItemEvent,
    type SelectMealEvent,
    type FoodLogBackEvent,
    type LogFoodEvent,
    type LogMealEvent,
    type MapBarcodeChangeEvent,
} from './health-events.js';
import type { ScreenComponent } from '../../types/screen-component.js';
import { createComponentLogger } from '../../utils/component-logger.js';
import { safeExec } from '../../utils/safe-exec.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../_shared/screen-status.js';

export class HealthFoodEntryScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private foodLog: FoodLog | null = null;
    private queryValue: URLSearchParams | null = null;
    private dateValue: string | null = null;
    private mealValue: string | null = null;
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);
    private readonly log = createComponentLogger('health-food-entry-screen');

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    set date(value: string | null) {
        this.dateValue = value;
    }

    set meal(value: string | null) {
        this.mealValue = value;
    }

    set query(value: URLSearchParams | null) {
        this.queryValue = value;
        if (this.initialized) {
            this.syncViewFromQuery();
        }
    }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;

        const page = buildSectionPage(this, 'Health', 'health', '/health');
        this.foodLog = document.createElement('food-log') as FoodLog;
        this.foodLog.showScanBarcodeAction = true;
        this.foodLog.showAiEstimateAction = true;
        // Story 338: offered here and only here — this screen is both the
        // manual-entry surface and where a dead-ended scan (337/340) lands.
        this.foodLog.showLabelReadAction = true;

        if (this.mealValue) {
            this.foodLog.defaultMealType = this.mealValue;
        }

        this.foodLog.addEventListener(HEALTH_EVENTS.SELECT_LIBRARY_ITEM, (event: SelectLibraryItemEvent) => {
            const item = event.detail;
            // Story 342: is the entry we are leaving the scan itself? Then it is a step,
            // not a destination — the scanner already replaces its own entry for the same
            // reason (`health-scanner-screen.component.ts`). Replacing it means Back from
            // the food returns to the search view instead of re-resolving the code and
            // landing on the same food, which reads as a frozen Back button.
            const leavingTheScan = Boolean(this.queryValue?.get('barcode') || this.pendingMapBarcode());
            void this.mapPendingBarcodeTo(item.id).then((bound) => {
                // Story 342: the question is answered, so retire it from the URL and
                // carry what was bound instead — the detail view this lands on confirms
                // it. `mapPendingBarcodeTo` swallows its own failures, so this always
                // navigates; a failed map simply carries nothing.
                //
                // `barcode` has to go too: `syncViewFromQuery` checks it BEFORE
                // `libraryId`, so a leftover scan param would re-run the lookup and the
                // picked item would never be shown.
                this.navigateWithParams(
                    { libraryId: item.id, barcode: null, mapBarcode: null, boundBarcode: bound },
                    leavingTheScan ? { history: 'replace' } : undefined,
                );
            });
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.SELECT_OFF_ITEM, (event: SelectOffItemEvent) => {
            const product = event.detail;
            if (!product.barcode) {
                // OFF entries without a barcode cannot be reconstructed from URL state;
                // show the detail directly without touching history.
                this.foodLog!.showProduct(product);
                return;
            }
            // Story 340: this navigation rebuilds the screen, so a pending scan would be
            // lost with it. Carry it in the URL — the created food learns it at log time.
            // Story 344: only a consented code rides the URL. Its presence there IS the
            // consent — the rebuild re-arms the box from it, so no second param is needed
            // and an un-ticked offer simply does not survive the navigation.
            const pending = this.foodLog?.bindConsent ? this.foodLog.pendingBarcode : null;
            this.navigateWithParams(pending
                ? { barcode: product.barcode, mapBarcode: pending }
                : { barcode: product.barcode, mapBarcode: null });
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.SELECT_MEAL, (event: SelectMealEvent) => {
            this.navigateWithParam('mealId', event.detail.id);
        });

        // Story 342 — "Change" on the confirmation: put the code back in the URL and let
        // the rebuild land on the search view with the question re-armed. Re-binding
        // replaces the old mapping (340), so nothing has to be deleted first.
        this.foodLog.addEventListener(HEALTH_EVENTS.MAP_BARCODE_CHANGE, (event: MapBarcodeChangeEvent) => {
            this.navigateWithParams({
                mapBarcode: event.detail.barcode,
                boundBarcode: null,
                libraryId: null,
                barcode: null,
            });
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.FOOD_LOG_BACK, (event: FoodLogBackEvent) => {
            goBack(this.searchUrl());
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.SCAN_BARCODE, (event: ScanBarcodeEvent) => {
            navigate(this.subPath('scanner'));
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.AI_ESTIMATE, (event: AiEstimateEvent) => {
            navigate(this.subPath('ai-estimate'));
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.LOG_FOOD, (event: LogFoodEvent) => {
            const { respondWith: _settles, ...entry } = event.detail;
            const date = this.dateValue ?? appTodayString();
            // Story 260: the form's editable HH:MM anchors on the target date
            // in the app zone; a cleared field logs unstamped.
            const consumed_at = entry.consumed_time
                ? dateAndTimeToInstant(date, entry.consumed_time, getAppTimeZone())
                : undefined;
            // Story 371: the Log button stays disabled until this settles.
            event.detail.respondWith = safeExec(this, this.log, async () => {
                if (entry.kind === 'new') {
                    this.log.debug('LOG_FOOD via createFoodItemAndLog', {
                        date,
                        meal_type: entry.meal_type,
                        amount: entry.amount,
                        barcode: entry.new_food_item.barcode,
                        source: entry.new_food_item.source,
                    });
                    const created = await HealthService.createFoodItemAndLog(
                        entry.new_food_item,
                        { date, meal_type: entry.meal_type, amount: entry.amount, consumed_at },
                    );
                    // Story 340: the scan that started this dead-ended, and the user
                    // answered it by finding the product under a different code. Bind
                    // the code they actually scanned to the row that just appeared.
                    await this.mapPendingBarcodeTo(created.food_item.id);
                } else {
                    this.log.debug('LOG_FOOD via createConsumptionEntry', {
                        date,
                        meal_type: entry.meal_type,
                        amount: entry.amount,
                        food_item_id: entry.food_item_id,
                        updated: Boolean(entry.food_item_update),
                    });
                    const { kind: _kind, consumed_time: _time, food_item_update, ...rest } = entry;
                    // Story 353: a label read filled this row in. Write the numbers
                    // first, so the row is never left logged-against but still empty.
                    if (food_item_update) await HealthService.updateFoodItem(entry.food_item_id, food_item_update);
                    await HealthService.createConsumptionEntry({ ...rest, date, consumed_at });
                    // Story 369: a food suggested by an in-store item code was confirmed by
                    // logging it; the ticked box teaches the exact code scanned.
                    await this.mapPendingBarcodeTo(entry.food_item_id);
                }
                await this.returnToOrigin();
            });
        });

        this.foodLog.addEventListener(HEALTH_EVENTS.LOG_MEAL, (event: LogMealEvent) => {
            // Story 311: `ingredients` is the per-occurrence list, already
            // carrying final amounts — so `scale` is absent when it is present,
            // and the server rejects the two together.
            const { meal_id, meal_type, scale, ingredients, consumed_time } = event.detail;
            const date = this.dateValue ?? appTodayString();
            const consumed_at = consumed_time
                ? dateAndTimeToInstant(date, consumed_time, getAppTimeZone())
                : undefined;
            this.log.debug('LOG_MEAL', { meal_id, date, meal_type, scale, ingredients: ingredients?.length, consumed_at });
            event.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.logMeal(meal_id, { date, meal_type, scale, ingredients, consumed_at });
                await this.returnToOrigin();
            });
        });

        page.content.append(
            this.statusNodes.loadingNode,
            this.statusNodes.errorNode,
            this.statusNodes.retryNode,
        );
        this.statusNodes.retryNode.addEventListener('click', () => {
            this.statusMixin.clearStatus();
            this.syncViewFromQuery();
        });
        page.content.appendChild(this.foodLog);

        this.syncViewFromQuery();
    }

    /**
     * Story 340 — the barcode a dead-ended scan is waiting to be bound to a food.
     *
     * It lives in the URL, not on the component: picking an Open Food Facts result
     * navigates (`?barcode=`), which rebuilds this screen and would discard any field.
     * `navigateWithParam` sets one param and keeps the rest, so `mapBarcode` rides along
     * through the pick and is still there when the food is finally created.
     */
    private pendingMapBarcode(): string | null {
        return new URL(window.location.href).searchParams.get('mapBarcode');
    }

    /**
     * Bind the pending code to the food the user landed on — whichever way it got here:
     * still on the component (a library pick, mapped before navigating) or carried in
     * the URL (an OFF pick, which rebuilt this screen on the way).
     *
     * Never blocks: if the mapping call fails they still get their food, and the only
     * cost is being asked again.
     */
    private async mapPendingBarcodeTo(foodItemId: string): Promise<string | null> {
        const barcode = this.foodLog?.pendingBarcode ?? this.pendingMapBarcode();
        if (!barcode) return null;
        // Story 344: the pick is not consent. Picking a food is simply what you do when a
        // scan fails, and 342 let the binding ride along with it — which is how a code got
        // bound unnoticed on 2026-09-14. Only the ticked box authorises a write.
        if (!this.foodLog?.bindConsent) return null;
        this.foodLog?.setPendingBarcode(null);
        try {
            await HealthService.mapFoodItemBarcode(foodItemId, barcode);
            this.log.debug('mapped unresolved barcode', { foodItemId, barcode });
            return barcode;
        } catch (err) {
            this.log.warn('mapping an unresolved barcode failed; the pick still stands', err);
            return null;
        }
    }

    private navigateWithParam(key: string, value: string): void {
        this.navigateWithParams({ [key]: value });
    }

    /** `null` deletes the param — story 342 retires `mapBarcode` once it is answered. */
    private navigateWithParams(params: Record<string, string | null>, options?: NavigateOptions): void {
        const url = new URL(window.location.href);
        for (const [key, value] of Object.entries(params)) {
            if (value === null) url.searchParams.delete(key);
            else url.searchParams.set(key, value);
        }
        navigate(url.pathname + url.search, options);
    }

    private searchUrl(): string {
        return this.dateValue && this.mealValue
            ? `/health/food-entry/${encodeURIComponent(this.dateValue)}/${encodeURIComponent(this.mealValue)}`
            : '/health/food-entry';
    }

    private subPath(segment: 'scanner' | 'ai-estimate'): string {
        return this.dateValue && this.mealValue
            ? `/health/${segment}/${encodeURIComponent(this.dateValue)}/${encodeURIComponent(this.mealValue)}`
            : `/health/${segment}`;
    }

    private syncViewFromQuery(): void {
        if (!this.foodLog) return;

        const barcode = this.queryValue?.get('barcode');
        const libraryId = this.queryValue?.get('libraryId');
        const mealId = this.queryValue?.get('mealId');

        if (barcode) {
            void this.foodLog.lookupBarcode(barcode).then(() => {
                // Story 340: a rebuilt screen restores the pending question from the URL.
                // A *successful* lookup keeps it — picking an OFF product under a
                // different code is still an answer to the original scan.
                // Story 344: a carried code was already consented to — re-arm it ticked.
                const carried = this.pendingMapBarcode();
                if (carried) this.foodLog?.setPendingBarcode(carried, true);
            });
        } else if (libraryId) {
            // Story 342: the confirmation rides the URL for the same reason the question
            // does — the pick navigates, and that rebuilds this screen. `showLibraryItem`
            // fills in the food's name once it has loaded.
            this.foodLog.setBoundBarcode(this.queryValue?.get('boundBarcode') ?? null);
            void this.foodLog.lookupLibraryItem(libraryId);
        } else if (mealId) {
            void this.foodLog.lookupMeal(mealId);
        } else {
            this.foodLog.showSearchView();
            // Story 340/344: re-entering the search view (including after a rebuild)
            // restores the offer. A code in the URL is one that was already consented to,
            // so it comes back ticked; absent, nothing is armed and nothing can bind.
            this.foodLog.setPendingBarcode(this.pendingMapBarcode(), true);
        }
    }

    /**
     * Story 291: leave the whole add-food flow. The flow is declared on the
     * routes, so this no longer restates it; the target names the day we want
     * to be on, which `exitFlow` pushes only when it is not already below the
     * flow (it is, when the flow was entered from the day screen).
     */
    private async returnToOrigin(): Promise<void> {
        await exitFlow(this.dateValue
            ? `/health/day/${encodeURIComponent(this.dateValue)}`
            : undefined);
    }
}

if (!customElements.get('health-food-entry-screen')) {
    customElements.define('health-food-entry-screen', HealthFoodEntryScreen);
}
