import stylesText from './meal-log-detail.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { formatMacro } from '../../../utils/format-macro.js';
import {
    MEAL_TYPES,
    nowHHMM,
    type FoodItem,
    type MealType,
    type MealWithIngredients,
    computeSnapshotMacros,
} from '@motivation/shared';
import { getAppTimeZone } from '../../../services/app-timezone.service.js';
import {
    HEALTH_EVENTS,
    createFoodLogBackEvent,
    createLogMealEvent,
    type AddIngredientEvent,
} from '../health-events.js';
import { getDefaultMealType } from '../health-utils.js';
import { dispatchAndSettle, whileBusy } from '../../../utils/in-flight.js';
import '../meal-ingredient-picker/meal-ingredient-picker.component.js';
import type { MealIngredientPicker } from '../meal-ingredient-picker/meal-ingredient-picker.component.js';

const styles = cssStyleSheet(stylesText);

/** Scale step, and the floor below which a meal stops being a meal. */
const SCALE_STEP = 0.1;
const SCALE_MIN = 0.1;

/** One line of what is about to be logged — a template row, edited, or added. */
interface LogLine {
    food_item: FoodItem;
    /** FINAL amount, in the food's base unit. Blank input → null, which blocks Log. */
    amount: number | null;
    /** True for a food this meal does not have (story 311's "I also had…"). */
    added: boolean;
}

const template = document.createElement('template');
template.innerHTML = `
    <div class="meal-detail">
        <div id="log-view">
            <div class="meal-header">
                <h3 class="meal-name" id="meal-name"></h3>
                <span class="meal-notes" id="meal-notes"></span>
            </div>

            <div class="scale-row">
                <label for="meal-scale">Scale</label>
                <button type="button" class="scale-step" id="scale-minus" aria-label="Less">−</button>
                <input type="number" id="meal-scale" min="0.1" step="0.1">
                <button type="button" class="scale-step" id="scale-plus" aria-label="More">+</button>
                <span id="scale-hint" class="meal-notes"></span>
            </div>

            <div class="meal-type-row">
                <label for="meal-type">Meal</label>
                <select id="meal-type">
                    ${MEAL_TYPES.map(m => `<option value="${m}">${m}</option>`).join('\n                    ')}
                </select>
                <label for="consumed-time">Time</label>
                <input type="time" id="consumed-time">
            </div>

            <ul class="ingredient-list" id="ingredient-list"></ul>
            <p class="add-error" id="add-error" hidden></p>
            <button type="button" class="btn-add-ingredient" id="add-ingredient-btn">+ Add ingredient</button>

            <div class="totals">
                <span class="total-cal"><span id="total-cal">0</span> kcal</span>
                <span>P: <span id="total-p">0</span>g</span>
                <span>C: <span id="total-c">0</span>g</span>
                <span>F: <span id="total-f">0</span>g</span>
            </div>

            <div class="actions">
                <button class="btn-back" id="back-btn">← Back</button>
                <button class="btn-log" id="log-btn">Log Meal</button>
            </div>
        </div>

        <div id="picker-view" hidden></div>
    </div>
`;

/**
 * Log a meal template into a day. Story 311: the ingredient list is editable
 * **for this occurrence only** — amounts, removals, and additions through the
 * shared `<meal-ingredient-picker>` — because a template that is close but not
 * exact used to mean logging it and then editing the day.
 *
 * The amount inputs hold FINAL amounts, so what is on screen is what gets
 * logged. `Scale` is a pre-fill: stepping it re-fills every row from
 * `template × scale`, and the event carries the resolved list with no scale, so
 * the server never multiplies a number the user typed (story 311 design note).
 *
 * The picker's ADD_INGREDIENT / PICKER_CANCEL are handled and **stopped** here,
 * the same boundary the meals screen uses, so the food-entry screen above never
 * has to know this view has two states.
 */
export class MealLogDetail extends HTMLElement {
    private mealValue: MealWithIngredients | null = null;
    private defaultMealTypeValue: MealType | null = null;
    /** What will be logged. Seeded from the template on every `showMeal`. */
    private lines: LogLine[] = [];

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    connectedCallback(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('back-btn')!.addEventListener('click', () => this.dispatchEvent(createFoodLogBackEvent()));
        // Story 371: held until the log settles, so a double tap logs once.
        const logBtn = shadow.getElementById('log-btn') as HTMLButtonElement;
        logBtn.addEventListener('click', () => void whileBusy(logBtn, () => this.handleLog()));
        shadow.getElementById('scale-minus')!.addEventListener('click', () => this.stepScale(-SCALE_STEP));
        shadow.getElementById('scale-plus')!.addEventListener('click', () => this.stepScale(+SCALE_STEP));
        // Typing a scale is still allowed; it re-fills the same way stepping does.
        shadow.getElementById('meal-scale')!.addEventListener('input', () => this.refillFromScale());
        shadow.getElementById('add-ingredient-btn')!.addEventListener('click', () => this.openPicker());

        this.applyMealTypeSelection();
    }

    set defaultMealType(mealType: string | null) {
        if (!mealType || !MEAL_TYPES.includes(mealType as MealType)) {
            this.defaultMealTypeValue = null;
        } else {
            this.defaultMealTypeValue = mealType as MealType;
        }
        this.applyMealTypeSelection();
    }

    showMeal(meal: MealWithIngredients): void {
        this.mealValue = meal;
        const shadow = this.shadowRoot!;
        shadow.getElementById('meal-name')!.textContent = meal.name;
        shadow.getElementById('meal-notes')!.textContent = meal.notes ?? '';

        const scaleInput = shadow.getElementById('meal-scale') as HTMLInputElement;
        scaleInput.value = String(meal.default_scale);
        shadow.getElementById('scale-hint')!.textContent = meal.default_scale === 1 ? '' : `(default ${meal.default_scale}×)`;

        // A fresh meal starts from its own template — no edits, removals or
        // additions carried over from whatever was shown before.
        this.closePicker();
        this.clearAddError();
        this.seedLinesFromTemplate();

        this.applyMealTypeSelection();
        this.render();
    }

    /** Template × current scale, which is also what stepping Scale returns to. */
    private seedLinesFromTemplate(): void {
        const scale = this.getCurrentScale();
        this.lines = (this.mealValue?.ingredients ?? []).map((ing) => ({
            food_item: ing.food_item,
            amount: roundAmount(ing.amount * scale),
            added: false,
        }));
    }

    private applyMealTypeSelection(): void {
        const select = this.shadowRoot?.getElementById('meal-type') as HTMLSelectElement | null;
        if (!select) return;
        select.value = this.defaultMealTypeValue ?? getDefaultMealType();
        // Eaten-at default: "now" in the app zone, editable (story 260).
        const timeInput = this.shadowRoot?.getElementById('consumed-time') as HTMLInputElement | null;
        if (timeInput) {
            timeInput.value = nowHHMM(getAppTimeZone());
        }
    }

    /**
     * Step the scale by a tenth, floored at SCALE_MIN. Rounded because
     * 1 + 0.1 × 3 is 1.3000000000000003 in float, and that reaches the input.
     */
    private stepScale(delta: number): void {
        const input = this.shadowRoot!.getElementById('meal-scale') as HTMLInputElement;
        const next = Math.max(SCALE_MIN, Math.round((this.getCurrentScale() + delta) * 10) / 10);
        input.value = String(next);
        this.refillFromScale();
    }

    /**
     * Re-fill every amount from the template. This deliberately discards typed
     * amounts: Scale means "the whole meal, this much", so leaving one hand-set
     * row behind would make the number on screen not the number scaled.
     * Added foods keep their own amount — they are not in the template to scale.
     */
    private refillFromScale(): void {
        const scale = this.getCurrentScale();
        const templateByFood = new Map((this.mealValue?.ingredients ?? []).map((i) => [i.food_item_id, i.amount]));
        for (const line of this.lines) {
            const base = templateByFood.get(line.food_item.id);
            if (base !== undefined) line.amount = roundAmount(base * scale);
        }
        this.render();
    }

    /**
     * The picker is built on demand and torn down on close, rather than sitting
     * hidden in the template. Two reasons, and the first is not cosmetic: the
     * picker carries its own `#search-input`, and a second one inside
     * `<food-log>` makes every `food-log #search-input` selector in the e2e
     * suite ambiguous under Playwright's shadow-piercing — 20-odd call sites
     * across eight specs, for a component nobody opened. Second, a fresh
     * element means no stale query or results from the last time it was used.
     */
    private openPicker(): void {
        this.clearAddError();
        const shadow = this.shadowRoot!;
        const host = shadow.getElementById('picker-view')!;
        const picker = document.createElement('meal-ingredient-picker') as MealIngredientPicker;
        // Story 370 (pwa-nutrition-04): no Scan or AI here — a side trip would leave this view for
        // the food-entry screen's own flow and drop the meal being logged. And nothing the picker
        // raises goes past this boundary.
        picker.sideTrips = false;
        for (const type of [HEALTH_EVENTS.SCAN_BARCODE, HEALTH_EVENTS.AI_ESTIMATE, HEALTH_EVENTS.LOAD_MORE_OFF]) {
            picker.addEventListener(type, (event: Event) => event.stopPropagation());
        }
        picker.addEventListener(HEALTH_EVENTS.ADD_INGREDIENT, (event: AddIngredientEvent) => {
            // Handled here, the same boundary the meals screen uses, so the
            // food-entry screen above never learns this view has two states.
            event.stopPropagation();
            this.addLine(event.detail.food_item, event.detail.amount);
        });
        picker.addEventListener(HEALTH_EVENTS.PICKER_CANCEL, (event: Event) => {
            event.stopPropagation();
            this.closePicker();
        });
        host.replaceChildren(picker);
        host.hidden = false;
        shadow.getElementById('log-view')!.hidden = true;
    }

    private closePicker(): void {
        const shadow = this.shadowRoot;
        if (!shadow) return;
        const host = shadow.getElementById('picker-view')!;
        host.replaceChildren();
        host.hidden = true;
        shadow.getElementById('log-view')!.hidden = false;
    }

    /**
     * Append a picked food. A food already on the list is refused rather than
     * merged: one amount per food is the rule the meal itself now carries
     * (migration 035), and silently summing would hide which number was logged.
     */
    private addLine(food: FoodItem, amount: number): void {
        this.closePicker();
        if (this.lines.some((line) => line.food_item.id === food.id)) {
            this.showAddError(`${food.display_name} is already in this meal — change its amount instead.`);
            return;
        }
        this.clearAddError();
        this.lines.push({ food_item: food, amount: roundAmount(amount), added: true });
        this.render();
    }

    /**
     * By identity, not by index: a row's handler outlives its render only as
     * long as the indices hold, and an index captured before a re-render points
     * at whatever moved into that slot.
     */
    private removeLine(line: LogLine): void {
        const index = this.lines.indexOf(line);
        if (index < 0) return;
        this.lines.splice(index, 1);
        this.clearAddError();
        this.render();
    }

    private showAddError(message: string): void {
        const el = this.shadowRoot!.getElementById('add-error')!;
        el.textContent = message;
        el.hidden = false;
    }

    private clearAddError(): void {
        const el = this.shadowRoot?.getElementById('add-error');
        if (!el) return;
        el.textContent = '';
        el.hidden = true;
    }

    private render(): void {
        this.renderIngredientList();
        this.renderTotals();
        this.updateLogEnabled();
    }

    private renderIngredientList(): void {
        const list = this.shadowRoot!.getElementById('ingredient-list')!;
        list.replaceChildren();
        for (const line of this.lines) {
            list.appendChild(this.ingredientRow(line));
        }
    }

    private ingredientRow(line: LogLine): HTMLElement {
        const li = document.createElement('li');
        li.className = 'ingredient-row';

        const name = document.createElement('span');
        name.className = 'ingredient-name';
        name.textContent = line.food_item.display_name;
        if (line.added) {
            const tag = document.createElement('span');
            tag.className = 'ingredient-added-tag';
            tag.textContent = 'added';
            name.appendChild(tag);
        }

        // The amount is a real input, not a label: editing it in place is the
        // point of the story. It carries the FINAL amount.
        const amountWrap = document.createElement('span');
        amountWrap.className = 'ingredient-amount';
        const input = document.createElement('input');
        input.type = 'number';
        input.className = 'ingredient-amount-input';
        input.min = '0';
        input.step = 'any';
        input.value = line.amount === null ? '' : String(line.amount);
        input.setAttribute('aria-label', `${line.food_item.display_name} amount`);
        input.addEventListener('input', () => {
            const parsed = Number.parseFloat(input.value);
            line.amount = Number.isFinite(parsed) ? parsed : null;
            // Re-render the row's kcal and the totals, but NOT the inputs —
            // rebuilding them mid-keystroke would move the caret.
            this.renderTotals();
            this.updateLogEnabled();
            cal.textContent = `${formatMacro(lineKcal(line))} kcal`;
        });
        amountWrap.append(input, document.createTextNode(line.food_item.base_unit));

        const cal = document.createElement('span');
        cal.className = 'ingredient-cal';
        cal.textContent = `${formatMacro(lineKcal(line))} kcal`;

        const remove = document.createElement('button');
        remove.type = 'button';
        remove.className = 'ingredient-remove';
        remove.textContent = '×';
        remove.setAttribute('aria-label', `Remove ${line.food_item.display_name}`);
        remove.addEventListener('click', () => this.removeLine(line));

        li.append(name, amountWrap, cal, remove);
        return li;
    }

    private renderTotals(): void {
        let cal = 0, p = 0, c = 0, f = 0;
        for (const line of this.lines) {
            const macros = computeSnapshotMacros(line.food_item, line.amount ?? 0);
            cal += macros.calories ?? 0;
            p += macros.protein_g ?? 0;
            c += macros.carbs_g ?? 0;
            f += macros.fat_g ?? 0;
        }
        const shadow = this.shadowRoot!;
        shadow.getElementById('total-cal')!.textContent = formatMacro(cal);
        shadow.getElementById('total-p')!.textContent = formatMacro(p);
        shadow.getElementById('total-c')!.textContent = formatMacro(c);
        shadow.getElementById('total-f')!.textContent = formatMacro(f);
    }

    /** An occurrence with nothing in it, or a blank/zero amount, is not a log. */
    private updateLogEnabled(): void {
        const btn = this.shadowRoot!.getElementById('log-btn') as HTMLButtonElement;
        btn.disabled = !this.resolveLines();
    }

    /** The final list, or null when it is not loggable. */
    private resolveLines(): Array<{ food_item_id: string; amount: number }> | null {
        if (this.lines.length === 0) return null;
        const resolved: Array<{ food_item_id: string; amount: number }> = [];
        for (const line of this.lines) {
            if (line.amount === null || !Number.isFinite(line.amount) || line.amount <= 0) return null;
            resolved.push({ food_item_id: line.food_item.id, amount: line.amount });
        }
        return resolved;
    }

    private getCurrentScale(): number {
        const input = this.shadowRoot?.getElementById('meal-scale') as HTMLInputElement | null;
        if (!input) return this.mealValue?.default_scale ?? 1;
        const parsed = Number.parseFloat(input.value);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : (this.mealValue?.default_scale ?? 1);
    }

    private getSelectedMealType(): MealType {
        const select = this.shadowRoot?.getElementById('meal-type') as HTMLSelectElement | null;
        return (select?.value as MealType) ?? getDefaultMealType();
    }

    private async handleLog(): Promise<void> {
        if (!this.mealValue) return;
        const ingredients = this.resolveLines();
        if (!ingredients) return;
        const time = (this.shadowRoot?.getElementById('consumed-time') as HTMLInputElement | null)?.value;
        await dispatchAndSettle(this, createLogMealEvent({
            meal_id: this.mealValue.id,
            date: '',  // Filled in by the screen, which holds the date.
            meal_type: this.getSelectedMealType(),
            // Story 311: the resolved final amounts, and therefore NO scale —
            // the server rejects both together, and these already include it.
            ingredients,
            consumed_time: time ? time : null,
        }));
    }
}

/** Amounts are grams or pieces, not physics — one decimal is the useful precision. */
function roundAmount(value: number): number {
    return Math.round(value * 10) / 10;
}

function lineKcal(line: LogLine): number {
    return computeSnapshotMacros(line.food_item, line.amount ?? 0).calories ?? 0;
}

if (!customElements.get('meal-log-detail')) {
    customElements.define('meal-log-detail', MealLogDetail);
}
